24	Fragment makeGemmFragment8x8() {
25	  IterVar i = make_itervar("i", 8);
26	  IterVar j = make_itervar("j", 8);
27	  IterVar rep = make_itervar("rep", 1);
28	  PrimExpr forward_thread = FloorDiv(j->var, 2) + 4 * i;
29	  PrimExpr index = FloorMod(j->var, 2);
30	  return Fragment({i, j}, {index}, forward_thread, rep);
31	}
32	/*
33	From https://github.com/RadeonOpenCompute/amd_matrix_instruction_calculator
34	./matrix_calculator.py --architecture cdna1 --instruction v_mfma_f32_16x16x16f16
35	--detail-instruction
36	*/
37	Fragment makeGemmFragmentAB16x16CDNA() {
38	  IterVar i = make_itervar("i", 16);
39	  IterVar j = make_itervar("j", 16);
40	  IterVar rep = make_itervar("rep", 1);
41	  PrimExpr forward_thread = 16 * FloorDiv(j->var, 4) + i;
42	  PrimExpr index = FloorMod(j->var, 4);
43	  return Fragment({i, j}, {index}, forward_thread, rep);
44	}
