82	Fragment makeGemmFragmentC_F64(const int block_m, const int block_n,
83	                               const int warp_m, const int warp_n) {
84	  ICHECK(block_m % warp_m == 0);
85	  ICHECK(block_n % warp_n == 0);
86	  ICHECK(warp_m % 16 == 0);
87	  ICHECK(warp_n % 8 == 0);
88	  auto base_layout = makeGemmFragment8x8();
89	  auto warp_layout =
90	      base_layout->Repeat({block_m / warp_m, block_n / warp_n}, true, false);
91	  auto block_layout =
92	      warp_layout->Repeat({warp_m / 8, warp_n / 8}, false, false);
93	  return block_layout;
94	}
