96	Fragment makeGemmFragmentC(const int block_m, const int block_n,
97	                           const int warp_m, const int warp_n,
98	                           const int element_size) {
99	  if (element_size == 64)
100	    return makeGemmFragmentC_F64(block_m, block_n, warp_m, warp_n);
101	  ICHECK(block_m % warp_m == 0);
102	  ICHECK(block_n % warp_n == 0);
103	  ICHECK(warp_m % 16 == 0) << "warp_m=" << warp_m;
104	  ICHECK(warp_n % 8 == 0) << "warp_n=" << warp_n;
105	  auto base_layout = makeGemmFragment8x8()->Repeat({2, 1}, false);
106	  auto warp_layout =
107	      base_layout->Repeat({block_m / warp_m, block_n / warp_n}, true, false);
108	  auto block_layout =
109	      warp_layout->Repeat({warp_m / 16, warp_n / 8}, false, false);
110	  return block_layout;
111	}
