120	  ICHECK(warp_m % 16 == 0) << "warp_m=" << warp_m;
121	  ICHECK(warp_n % 16 == 0) << "warp_n=" << warp_n;
122	  auto base_layout = makeGemmFragmentC16x16CDNA()->Repeat({1, 1}, false);
123	  auto warp_layout =
124	      base_layout->Repeat({warp_m / 16, warp_n / 16}, false, true);
125	  auto block_layout =
126	      warp_layout->Repeat({block_m / warp_m, block_n / warp_n}, true, false);
