130	Fragment makeGemmFragmentCHopper(const int block_m, const int block_n,
131	                                 const int warp_m, const int warp_n,
132	                                 const int element_size) {
133	  ICHECK(block_m % warp_m == 0);
134	  // ICHECK(block_n == warp_n);
135	  ICHECK(warp_m % 16 == 0) << "warp_m=" << warp_m;
136	  auto warp_layout = makeGemmFragment8x8()->Repeat({2, warp_n / 8}, false,
137	                                                   false); // 16 x N (1 warp)
138	  auto block_layout = warp_layout->Repeat({block_m / warp_m, block_n / warp_n},
139	                                          true, false); // 16*Y x N (Y warp)
140	  return block_layout->Repeat({warp_m / 16, 1}, false, false);
141	}
