143	Fragment makeGemmFragmentA(const int block_m, const int block_n,
144	                           const int block_k, const int warp_m,
145	                           const int warp_n, const int element_size,
146	                           bool transposed) {
147	  // assume not transposed
148	  ICHECK(block_m % warp_m == 0);
149	  ICHECK(block_n % warp_n == 0);
150	  ICHECK(warp_m % 16 == 0);
151	  ICHECK(block_k % 16 == 0);
152	  // Only support 8-bit and 16-bit
153	  ICHECK(element_size == 8 || element_size == 16)
154	      << "element bitwidth=" << element_size;
155	
156	  if (transposed) {
157	    auto base_layout =
158	        makeGemmFragment8x8Transposed()->Repeat({2, 2}, false, true);
159	    auto warp_layout = base_layout->Repeat({1, block_m / warp_m}, true, false)
160	                           ->Replicate(block_n / warp_n);
161	    auto block_layout =
162	        warp_layout->Repeat({block_k / 16, warp_m / 16}, false, true);
163	    return block_layout;
164	  } else {
165	    if (element_size == 8) {
166	      auto base_layout = makeGemmFragment8x16()->Repeat({2, 2}, false, false);
167	      auto warp_layout = base_layout->Repeat({block_m / warp_m, 1}, true)
168	                             ->Replicate(block_n / warp_n);
169	      auto block_layout =
170	          warp_layout->Repeat({warp_m / 16, block_k / 32}, false, false);
171	      return block_layout;
172	    } else if (element_size == 16) {
173	      auto base_layout = makeGemmFragment8x8()->Repeat({2, 2}, false, false);
174	      auto warp_layout = base_layout->Repeat({block_m / warp_m, 1}, true)
175	                             ->Replicate(block_n / warp_n);
176	      auto block_layout =
177	          warp_layout->Repeat({warp_m / 16, block_k / 16}, false, false);
178	      return block_layout;
179	    } else {
180	      ICHECK(0);
181	      return Fragment();
182	    }
183	  }
184	}
