186	Fragment makeGemmFragmentB(const int block_m, const int block_n,
187	                           const int block_k, const int warp_m,
188	                           const int warp_n, bool transposed) {
189	  // transposed
190	  ICHECK(warp_n % 8 == 0);
191	  ICHECK(block_k % 16 == 0);
192	  if (transposed) {
193	    auto base_layout = makeGemmFragment8x8()->Repeat({1, 2}, false, false);
194	    auto warp_layout = base_layout->Replicate(block_m / warp_m)
195	                           ->Repeat({block_n / warp_n, 1}, true, false);
196	    auto block_layout =
197	        warp_layout->Repeat({warp_n / 8, block_k / 16}, false, false);
198	    return block_layout;
199	  } else {
200	    auto base_layout =
201	        makeGemmFragment8x8Transposed()->Repeat({2, 1}, false, false);
202	    auto warp_layout = base_layout->Replicate(block_m / warp_m)
203	                           ->Repeat({1, block_n / warp_n}, true);
204	    auto block_layout =
205	        warp_layout->Repeat({block_k / 16, warp_n / 8}, false, true);
206	    return block_layout;
207	  }
208	}
