240	Fragment makeGemmFragment32x32(int element_size) {
241	  IterVar i = make_itervar("i", 32);
242	  IterVar j = make_itervar("j", 32);
243	  IterVar rep = make_itervar("rep", 1);
244	  ICHECK(element_size == 16 || element_size == 32);
245	  if (element_size == 16) {
246	    PrimExpr thd = FloorMod(i, 4) + FloorDiv(FloorMod(i, 16), 8) * 4 +
247	                   FloorDiv(FloorMod(j, 16), 8) * 8 + FloorDiv(i, 16) * 16;
248	    PrimExpr idx = FloorMod(j, 4) + FloorDiv(j, 16) * 4 +
249	                   FloorDiv(FloorMod(i, 8), 4) * 8 +
250	                   FloorDiv(FloorMod(j, 8), 4) * 16;
251	    return Fragment({i, j}, {idx}, thd, rep);
252	  } else {
253	    PrimExpr thd = FloorMod(i, 2) + 2 * FloorDiv(FloorMod(j, 4), 2) +
254	                   FloorDiv(FloorMod(i, 16), 8) * 4 +
255	                   FloorDiv(FloorMod(j, 16), 8) * 8 + FloorDiv(i, 16) * 16;
256	    PrimExpr idx = FloorMod(j, 2) + 2 * FloorDiv(FloorMod(i, 4), 2) +
257	                   FloorDiv(j, 16) * 4 + FloorDiv(FloorMod(i, 8), 4) * 8 +
258	                   FloorDiv(FloorMod(j, 8), 4) * 16;
259	    return Fragment({i, j}, {idx}, thd, rep);
260	  }
261	}
