278	Fragment makeGemmVoltaFragmentA(const int block_m, const int block_n,
279	                                const int block_k, const int warp_m,
280	                                const int warp_n) {
281	  // assume not transposed
282	  ICHECK(block_m % warp_m == 0);
283	  ICHECK(block_n % warp_n == 0);
284	  ICHECK(warp_m % 32 == 0);
285	  ICHECK(block_k % 4 == 0);
286	  // this is a special case
287	  IterVar i = make_itervar("i", 32);
288	  IterVar j = make_itervar("j", 4);
289	  IterVar rep = make_itervar("rep", 2);
290	  PrimExpr thd = FloorDiv(FloorMod(i, 16), 8) * 4 + 16 * FloorDiv(i, 16) +
291	                 FloorMod(i, 4) + 8 * rep;
292	  PrimExpr idx = j + FloorDiv(FloorMod(i, 8), 4) * 4;
293	  Fragment base_layout = Fragment({i, j}, {idx}, thd, rep);
294	  auto warp_layout =
295	      base_layout->Repeat({warp_m / 32, block_k / 4}, false, false);
296	  auto block_layout = warp_layout->Replicate(block_n / warp_n)
297	                          ->Repeat({block_m / warp_m, 1}, true);
298	  return block_layout;
299	}
