301	PrimExpr xor2x2(const PrimExpr &i, const PrimExpr &j) {
302	  return FloorMod(i + j, 2);
303	}
304	
305	PrimExpr xor4x4(const PrimExpr &i, const PrimExpr &j) {
306	  PrimExpr i0 = FloorMod(i, 2);
307	  PrimExpr j0 = FloorMod(j, 2);
308	  PrimExpr i1 = FloorDiv(i, 2);
309	  PrimExpr j1 = FloorDiv(j, 2);
310	  return 2 * xor2x2(i1, j1) + xor2x2(i0, j0);
311	}
312	
313	PrimExpr xor8x8(const PrimExpr &i, const PrimExpr j) {
314	  PrimExpr i0 = FloorMod(i, 2);
315	  PrimExpr j0 = FloorMod(j, 2);
316	  PrimExpr i1 = FloorDiv(i, 2);
317	  PrimExpr j1 = FloorDiv(j, 2);
318	  return 2 * xor4x4(i1, j1) + xor2x2(i0, j0);
319	}
