321	Layout makeHalfBankSwizzleLayout(int stride, int continuous, int element_size) {
322	  // Swizzle 2 bit
323	  Var i = InputPlaceholder(0);
324	  Var j = InputPlaceholder(1);
325	  int vector_size = 128 / element_size;
326	  ICHECK(stride % 8 == 0) << "stride=" << stride;
327	  ICHECK(continuous % (vector_size * 4) == 0)
328	      << "continuous=" << continuous << ", vector_size=" << vector_size;
329	  PrimExpr ts = FloorDiv(i, 8);
330	  PrimExpr s = FloorMod(i, 8);
331	  PrimExpr tc = FloorDiv(FloorDiv(j, vector_size), 4);
332	  PrimExpr c = FloorMod(FloorDiv(j, vector_size), 4);
333	  PrimExpr vec = FloorMod(j, vector_size);
334	  PrimExpr c_swizzle = xor4x4(c, FloorDiv(s, 2));
335	  PrimExpr index = vec + (c_swizzle + s * 4) * vector_size;
336	  return Layout(Array<PrimExpr>{stride, continuous}, {tc, ts, index});
337	}
