339	Layout makeFullBankSwizzleLayout(int stride, int continuous, int element_size) {
340	  // Swizzle 3 bit
341	  Var i = InputPlaceholder(0);
342	  Var j = InputPlaceholder(1);
343	  int vector_size = 128 / element_size;
344	  ICHECK(stride % 8 == 0) << "stride=" << stride;
345	  ICHECK(continuous % (vector_size * 8) == 0)
346	      << "continuous=" << continuous << ", vector_size=" << vector_size;
347	  PrimExpr ts = FloorDiv(i, 8);
348	  PrimExpr s = FloorMod(i, 8);
349	  PrimExpr tc = FloorDiv(FloorDiv(j, vector_size), 8);
350	  PrimExpr c = FloorMod(FloorDiv(j, vector_size), 8);
351	  PrimExpr vec = FloorMod(j, vector_size);
352	  PrimExpr c_swizzle = xor8x8(c, s);
353	  PrimExpr index = vec + (c_swizzle + s * 8) * vector_size;
354	  return Layout(Array<PrimExpr>{stride, continuous}, {tc, ts, index});
355	}
