357	// Detail implementation please ref to
358	// bitblas::tl::mfma_layout::make_mfma_swizzle_layout
359	Layout makeMatrixCoreSwizzleLayout(int stride, int continuous, int element_size,
360	                                   int kPack = 1) {
361	  const int numBanks = 32;
362	  const int bankBitWidth = 32;
363	  const int SIMDWidth = 16;
364	  const int vecSize = 4 * kPack;
365	  const int innerDimLength = continuous;
366	  const int typeWidthInBit = element_size;
367	
368	  const int elemsPerOneBanksRow = (numBanks * bankBitWidth) / typeWidthInBit;
369	  const int perPhase = std::max(1, elemsPerOneBanksRow / innerDimLength);
370	  const int maxPhase = std::min(SIMDWidth / perPhase, innerDimLength / vecSize);
371	
372	  IterVar row = make_itervar("row", stride);
373	  IterVar col = make_itervar("col", continuous);
374	  PrimExpr phase = FloorMod(row / perPhase, maxPhase);
375	  PrimExpr colOffSwizzled = ((col / vecSize) ^ phase) * vecSize;
376	  PrimExpr colOffOrdered = FloorMod(col, vecSize);
377	  PrimExpr colOff = colOffSwizzled + colOffOrdered;
378	
379	  return Layout(Array{row, col}, {row, colOff});
380	}
