382	Layout makeGemmABLayoutF64_Kinner(int stride, int continuous) {
383	  // Swizzle<2, 0, 4>
384	  Var i = InputPlaceholder(0);
385	  Var j = InputPlaceholder(1);
386	  PrimExpr tc = FloorDiv(j, 16);
387	  PrimExpr ts = FloorDiv(i, 4);
388	  PrimExpr c = FloorMod(j, 16);
389	  PrimExpr s = FloorMod(i, 4);
390	  PrimExpr swizzled_c = FloorDiv(c, 4) * 4 + xor4x4(FloorMod(c, 4), s);
391	  PrimExpr index = swizzled_c + s * 16;
392	  return Layout(Array<PrimExpr>{stride, continuous}, {tc, ts, index});
393	}
