395	Layout makeGemmABLayoutF64_Kouter(int stride, int continuous) {
396	  // Swizzle<2, 2, 2>
397	  Var i = InputPlaceholder(0);
398	  Var j = InputPlaceholder(1);
399	  PrimExpr tc = FloorDiv(j, 16);
400	  PrimExpr ts = FloorDiv(i, 4);
401	  PrimExpr c = FloorMod(j, 16);
402	  PrimExpr s = FloorMod(i, 4);
403	  PrimExpr swizzled_c = FloorMod(c, 4) + xor4x4(FloorDiv(c, 4), s) * 4;
404	  PrimExpr index = swizzled_c + s * 16;
405	  return Layout(Array<PrimExpr>{stride, continuous}, {tc, ts, index});
406	}
