408	// The Default Layout for Tensor Access
409	Layout makeGemmLayoutLinear(int stride, int continuous) {
410	  IterVar i = make_itervar("i", stride);
411	  IterVar j = make_itervar("j", continuous);
412	  return Layout(Array{i, j}, {i * continuous + j});
413	}
