415	Layout makeGemmABLayoutPadded(int stride, int continuous, int element_size) {
416	  IterVar i = make_itervar("i", stride);
417	  IterVar j = make_itervar("j", continuous);
418	  int padded = continuous;
419	  // Add 128 bits padding when the last dim is a multiple of 256 bits
420	  if ((element_size * continuous) % 256 == 0)
421	    padded += 128 / element_size;
422	  return Layout(Array{i, j}, {i * padded + j});
423	}
