425	Layout MakeGemmVoltaABLayoutCrosswise(int stride, int continuous) {
426	  ICHECK(stride % 32 == 0 && continuous % 32 == 0);
427	  IterVar i = make_itervar("i", stride);
428	  IterVar j = make_itervar("j", continuous);
429	  PrimExpr vec_contiguous_idx = FloorDiv(j, 4);
430	  PrimExpr vec_strided_within_tile = FloorMod(vec_contiguous_idx, 8);
431	
432	  PrimExpr bit2 =
433	      FloorMod(FloorDiv(FloorMod(i, 32), 16) + FloorDiv(FloorMod(i, 16), 8) +
434	                   FloorDiv(vec_strided_within_tile, 4),
435	               2);
436	  PrimExpr bit1 = xor2x2(FloorDiv(FloorMod(i, 8), 4),
437	                         FloorDiv(FloorMod(vec_strided_within_tile, 4), 2));
438	  PrimExpr permuted_vec_contiguous =
439	      FloorDiv(i, 16) * 16 + FloorMod(i, 4) * 4 + bit2 * 2 + bit1;
440	
441	  PrimExpr offset = FloorMod(j, 4) + permuted_vec_contiguous * 4 +
442	                    vec_contiguous_idx * stride * 4;
443	  return Layout(Array{i, j}, {offset});
444	}
