446	Layout MakeGemmVoltaALayoutCongruous(int stride, int continuous) {
447	  ICHECK(stride % 4 == 0 && continuous % 64 == 0);
448	  IterVar i = make_itervar("i", stride);
449	  IterVar j = make_itervar("j", continuous);
450	  PrimExpr vec_contiguous_idx = FloorDiv(j, 8);
451	  PrimExpr vec_strided_idx = i;
452	  PrimExpr tile_contiguous_idx = FloorDiv(vec_contiguous_idx, 8);
453	  PrimExpr tile_strided_idx = FloorDiv(vec_strided_idx, 4);
454	  PrimExpr tile_contiguous_residual = FloorMod(vec_contiguous_idx, 8);
455	  PrimExpr tile_strided_residual = FloorMod(vec_strided_idx, 4);
456	
457	  PrimExpr permuted_strided_within_tile = FloorDiv(tile_contiguous_residual, 2);
458	  PrimExpr permuted_contiguous_within_tile =
459	      FloorMod(tile_contiguous_residual, 2) * 4 +
460	      xor4x4(tile_strided_residual, permuted_strided_within_tile);
461	
462	  PrimExpr element_strided =
463	      permuted_strided_within_tile + tile_strided_idx * 4;
464	  PrimExpr element_contiguous =
465	      FloorMod(j, 8) +
466	      (permuted_contiguous_within_tile + tile_contiguous_idx * 8) * 8;
467	  PrimExpr offset = element_strided * continuous + element_contiguous;
468	  return Layout(Array{i, j}, {offset});
469	}
470	
471	Layout MakeGemmVoltaBLayoutCongruous(int stride, int continuous) {
472	  ICHECK(stride % 4 == 0 && continuous % 64 == 0);
473	  IterVar i = make_itervar("i", stride);
474	  IterVar j = make_itervar("j", continuous);
475	  PrimExpr vec_contiguous_idx = FloorDiv(j, 8);
476	  PrimExpr vec_strided_idx = i;
477	  PrimExpr tile_contiguous_idx = FloorDiv(vec_contiguous_idx, 8);
478	  PrimExpr tile_strided_idx = FloorDiv(vec_strided_idx, 4);
479	  PrimExpr tile_contiguous_residual = FloorMod(vec_contiguous_idx, 8);
480	  PrimExpr tile_strided_residual = FloorMod(vec_strided_idx, 4);
481	
482	  PrimExpr permuted_strided_within_tile = FloorMod(tile_contiguous_residual, 4);
483	  PrimExpr permuted_contiguous_within_tile =
484	      FloorDiv(tile_contiguous_residual, 4) * 4 +
485	      xor4x4(tile_strided_residual, permuted_strided_within_tile);
486	
487	  PrimExpr element_strided =
488	      permuted_strided_within_tile + tile_strided_idx * 4;
489	  PrimExpr element_contiguous =
490	      FloorMod(j, 8) +
491	      (permuted_contiguous_within_tile + tile_contiguous_idx * 8) * 8;
492	  PrimExpr offset = element_strided * continuous + element_contiguous;
493	  return Layout(Array{i, j}, {offset});
494	}
495	
496	Layout makeGemmVoltaABLayout(int stride, int continuous, bool is_a,
497	                             int kfactor) {
498	  if (kfactor == 2)
499	    return MakeGemmVoltaABLayoutCrosswise(stride, continuous);
500	  if (is_a && continuous % 64 == 0)
501	    return MakeGemmVoltaALayoutCongruous(stride, continuous);
502	  if (!is_a && continuous % 64 == 0)
503	    return MakeGemmVoltaBLayoutCongruous(stride, continuous);
504	  return makeGemmABLayoutPadded(stride, continuous, 16);
505	}
506	
507	/*!
508	 * \brief Creates a memory layout for GEMM's A or B matrices.
509	 *
510	 * This function selects an appropriate memory layout based on the matrix
511	 * dimensions, element size, continuity, and a k-factor. It aims to optimize
512	 * memory access patterns, potentially using swizzling techniques or specialized
513	 * layouts for different data types and hardware characteristics.
514	 *
515	 * \param mat_stride The leading dimension of the matrix (e.g., K for a
516	 * row-major M x K matrix). This is the number of elements to skip to get to the
517	 * same column in the next row (row-major) or to the same row in the next column
518	 * (column-major). \param mat_continuous The length of the dimension stored
519	 * contiguously in memory (e.g., K for a row-major M x K matrix, or M for a
520	 * column-major M x K matrix). \param continuity The size of the dimension that
521	 * is continuous from the perspective of memory bank access. This is used to
522	 * select specific swizzling strategies. It might be the same as mat_continuous
523	 *                   or different based on tiling or hardware details.
524	 * \param element_size The size of each element in the matrix, in bits (e.g., 8,
525	 * 16, 32, 64). \param kfactor An integer factor that influences layout
526	 * selection, particularly for fp64 and int8 types. It often relates to how the
527	 * K dimension of the GEMM (M x K * K x N) is handled or tiled.
528	 *                - For fp64 (element_size == 64):
529	 *                  - kfactor == 1 often implies K is in the "outer" loop (e.g.,
530	 * KxN matrix).
531	 *                  - kfactor == 2 often implies K is in the "inner" loop (e.g.,
532	 * NxK matrix).
533	 *                - For int8 (element_size == 8):
534	 *                  - kfactor == 1 uses a padded layout.
535	 * \return A Layout object representing the chosen memory layout.
536	 */
537	Layout makeGemmABLayout(int mat_stride, int mat_continuous, int continuity,
538	                        int element_size, int kfactor) {
539	  if (element_size == 64) {
540	    if (kfactor == 1 && continuity % 16 == 0) // float64 KxN
541	      return makeGemmABLayoutF64_Kouter(mat_stride, mat_continuous);
542	    if (kfactor == 2 && continuity % 16 == 0) // float64 NxK
543	      return makeGemmABLayoutF64_Kinner(mat_stride, mat_continuous);
544	    return makeGemmABLayoutPadded(mat_stride, mat_continuous, element_size);
545	  }
546	  int vector_size = 128 / element_size;
547	  if (kfactor == 1 && element_size == 8) // int8 KxN
548	    return makeGemmABLayoutPadded(mat_stride, mat_continuous, element_size);
549	  else if (mat_continuous % (vector_size * 8) == 0)
550	    return makeFullBankSwizzleLayout(mat_stride, mat_continuous, element_size);
551	  else if (mat_continuous % (vector_size * 4) == 0)
552	    return makeHalfBankSwizzleLayout(mat_stride, mat_continuous, element_size);
553	  else {
554	    return makeGemmABLayoutPadded(mat_stride, mat_continuous, element_size);
555	  }
556	}
557	
558	Layout makeGemmABLayoutCDNA(int stride, int continuous, int element_size,
559	                            int kPack) {
560	  int vector_size = 128 / element_size;
561	  if (continuous % (vector_size * 4) == 0)
562	    return makeMatrixCoreSwizzleLayout(stride, continuous, element_size, kPack);
563	  else {
564	    return makeGemmABLayoutPadded(stride, continuous, element_size);
565	  }
566	}
567	} // namespace tl
568	} // namespace tvm
