33	 * \brief collect the mapping from the buffer var to it allocated buffer
34	 */
35	class ThreadBindingCollector : public StmtExprVisitor {
36	public:
37	  void VisitStmt_(const AttrStmtNode *op) final {
38	    if (op->attr_key == tir::attr::thread_extent) {
39	      IterVar iv = Downcast<IterVar>(op->node);
40	      thread_binding_[iv->var.get()] = iv;
41	    }
42	    StmtExprVisitor::VisitStmt_(op);
43	  }
44	
45	  // The thread binding map
46	  std::unordered_map<const VarNode *, IterVar> thread_binding_;
47	};
48	
49	using namespace tir;
50	using arith::IRMutatorWithAnalyzer;
51	using arith::IRVisitorWithAnalyzer;
52	
53	class ParallelLoopTransformer : public IRMutatorWithAnalyzer {
54	public:
55	  static Stmt Substitute(Stmt stmt, bool skip_thread_partition = false) {
56	    arith::Analyzer analyzer;
57	    ParallelLoopTransformer transformer(&analyzer);
58	    return transformer.VisitStmt(stmt);
59	  }
60	
61	  ParallelLoopTransformer(arith::Analyzer *analyzer)
62	      : IRMutatorWithAnalyzer(analyzer) {}
63	
64	  Stmt VisitStmt_(const ForNode *op) final {
65	    if (op->kind != ForKind::kParallel)
66	      return StmtMutator::VisitStmt_(op);
67	
68	    // Collect loop variables and ranges
69	    auto for_node = GetRef<For>(op);
70	    Array<Var> loop_vars;
71	    Array<PrimExpr> loop_extents;
72	    Stmt body = op->body;
73	
74	    // Bind the range of outer loop variables
75	    analyzer_->Bind(op->loop_var, Range::FromMinExtent(0, op->extent));
76	    loop_vars.push_back(op->loop_var);
77	    loop_extents.push_back(op->extent);
78	
79	    // If there are inner loops, bind their ranges as well
80	    while (const ForNode *inner = body.as<ForNode>()) {
81	      analyzer_->Bind(inner->loop_var, Range::FromMinExtent(0, inner->extent));
82	      loop_vars.push_back(inner->loop_var);
83	      loop_extents.push_back(inner->extent);
84	      body = inner->body;
85	    }
86	
87	    ICHECK(loop_vars.size() == loop_extents.size())
88	        << "loop_vars and loop_extents size mismatch";
89	
90	    // Collect buffer access information
91	    BufferAccessCollector collector;
92	    collector(op->body);
93	
94	    PrimExpr condition;
95	
96	    for (const auto &[buffer, indices] : collector.buffer_indices) {
97	      ICHECK(indices.size() == buffer->shape.size())
98	          << "indices size mismatch with buffer shape";
99	
100	      for (size_t i = 0; i < indices.size(); ++i) {
101	        auto index = indices[i];
102	        auto bound = analyzer_->const_int_bound(index);
103	        int64_t upper_bound = bound->max_value + 1;
104	        int64_t shape = Downcast<IntImm>(buffer->shape[i])->value;
105	
106	        // Collect the variables that used in the index
107	        std::unordered_set<Var, ObjectPtrHash, ObjectPtrEqual> used_vars;
108	        // post order visit the index
109	        PostOrderVisit(index, [&](const ObjectRef &obj) {
110	          if (const VarNode *v = obj.as<VarNode>()) {
111	            used_vars.insert(GetRef<Var>(v));
112	          }
113	        });
114	        if (used_vars.size() == 0) {
115	          continue;
116	        }
117	
118	        // find related loop vars
119	        Array<Var> related_loop_vars;
120	        for (size_t j = 0; j < loop_vars.size(); ++j) {
121	          auto loop_var = loop_vars[j];
122	          // if find related, pop the loop_vars and loop_extents
123	          if (used_vars.count(loop_var)) {
124	            related_loop_vars.push_back(loop_var);
125	          }
126	          ICHECK(related_loop_vars.size() <= 1)
127	              << "Only one related loop var is supported currently, but got "
128	              << related_loop_vars
129	              << " implement multiple loop vars may not be "
130	              << "too hard, please send an issue if you need "
131	              << "came up with this message.";
132	
133	          auto bound = analyzer_->const_int_bound(index);
134	          int64_t upper_bound = bound->max_value + 1;
135	          int64_t shape = Downcast<IntImm>(buffer->shape[i])->value;
136	          if (upper_bound < shape) {
137	            PrimExpr predicate = LT(index, IntImm(index.dtype(), upper_bound));
138	            condition =
139	                condition.defined() ? And(condition, predicate) : predicate;
140	
141	            // replace the buffer index from A[i, r * 2] with A[i, j]
142	            // where r is the original index, j is the loop_var
143	            auto index_map = tir::IndexMap({loop_var}, {index});
144	            auto inverse_index_map = index_map.Inverse(
145	                {Range::FromMinExtent(0, IntImm(index.dtype(), upper_bound))},
146	                analyzer_);
147	
148	            loop_extents.Set(i, IntImm(index.dtype(), shape));
149	            body = tir::Substitute(body,
150	                                   {{loop_var, inverse_index_map->MapIndices(
151	                                                   {loop_var}, analyzer_)[0]}});
152	          }
153	        }
154	      }
155	    }
156	    if (condition.defined()) {
157	      body = IfThenElse(condition, body);
158	      for (int j = loop_vars.size() - 1; j >= 0; --j) {
159	        auto loop_var = loop_vars[j];
160	        auto loop_extent = loop_extents[j];
161	        body = For(loop_var, 0, loop_extent, ForKind::kParallel, body);
162	      }
163	      return Downcast<For>(body);
164	    }
165	    // Only traverse the outer loop
166	    return for_node;
167	  }
168	
169	private:
170	  // Helper class for collecting buffer access information, only counts fragment
171	  // buffer access
172	  class BufferAccessCollector : public StmtExprVisitor {
173	  public:
174	    void VisitExpr_(const BufferLoadNode *op) final {
175	      if (op->buffer.scope() == "local.fragment") {
176	        if (buffer_indices.find(op->buffer) == buffer_indices.end()) {
177	          buffer_indices[op->buffer] = op->indices;
178	        } else {
179	          // check equal
180	          ICHECK(StructuralEqual()(buffer_indices[op->buffer], op->indices))
181	              << "indices mismatch for buffer: " << op->buffer;
182	        }
183	      }
184	      StmtExprVisitor::VisitExpr_(op);
185	    }
186	
187	    void VisitStmt_(const BufferStoreNode *op) final {
188	      if (op->buffer.scope() == "local.fragment") {
189	        if (buffer_indices.find(op->buffer) == buffer_indices.end()) {
190	          buffer_indices[op->buffer] = op->indices;
191	        } else {
192	          // check equal
193	          ICHECK(StructuralEqual()(buffer_indices[op->buffer], op->indices))
194	              << "indices mismatch for buffer: " << op->buffer;
195	        }
196	      }
197	      StmtExprVisitor::VisitStmt_(op);
198	    }
199	
200	    std::unordered_map<Buffer, Array<PrimExpr>, ObjectPtrHash, ObjectPtrEqual>
201	        buffer_indices;
202	  };
203	};
204	
205	struct LayoutInferenceResult {
206	  Map<Buffer, Layout> layout_map;
207	  Map<For, Fragment> for_map;
208	  Map<For, PrimExpr> predicate_map;
209	};
210	
211	class BufferUseDefCollector : public IRVisitorWithAnalyzer {
212	public:
213	  BufferUseDefCollector(bool skip_thread_partition)
214	      : skip_thread_partition_(skip_thread_partition) {}
215	
216	  LayoutInferenceResult Run() {
217	    // Basic consistency check: infer_list_ and thread_var_vec_ should have the
218	    // same size
219	    ICHECK_EQ(infer_list_.size(), thread_var_vec_.size())
220	        << "Size mismatch: infer_list_ and thread_var_vec_ must match in "
221	           "length.";
222	    ICHECK_EQ(thread_bounds_vec_.size(), infer_list_.size())
223	        << "Size mismatch: thread_bounds_vec_ and infer_list_ must match in "
224	           "length.";
225	
226	    // If needed, you can also check that annotated_layout_map_ is not empty, or
227	    // anything else relevant to your setup.
228	
229	    // Copy the annotated layout map to local variable
230	    Map<Buffer, Layout> layout_map = annotated_layout_map_;
231	    int num_infer = infer_list_.size();
232	
233	    // Prepare BFS queue for iterative inference
234	    std::queue<int> q;
235	    std::vector<bool> in_queue(num_infer, true);
236	    for (int i = 0; i < num_infer; i++) {
237	      // Check that each infer_list_ entry is valid
238	      ICHECK(infer_list_[i] != nullptr)
239	          << "infer_list_[" << i
240	          << "] is null. The inference object is not allocated properly.";
241	
242	      // Check that each thread_var_vec_ entry is defined
243	      if (!thread_var_vec_[i].defined() && skip_thread_partition_) {
244	        thread_var_vec_[i] = thread_var_;
245	      }
246	      q.push(i);
247	    }
248	    auto run_infer_step = [&](int cur_infer_id, InferLevel level,
249	                              bool update_queue) {
250	      // Range check for cur_infer_id
251	      ICHECK_GE(cur_infer_id, 0)
252	          << "cur_infer_id is negative, which is invalid.";
253	      ICHECK_LT(cur_infer_id, num_infer)
254	          << "cur_infer_id " << cur_infer_id << " is out of range, must be < "
255	          << num_infer << ".";
256	
257	      // Make sure we can safely access infer_list_[cur_infer_id] and
258	      // thread_var_vec_[cur_infer_id]
259	      auto &next = infer_list_[cur_infer_id];
260	      auto iter_var = thread_var_vec_[cur_infer_id];
261	      auto thread_bounds = thread_bounds_vec_[cur_infer_id];
262	      // Double-check that 'next' is valid
263	      ICHECK(next != nullptr) << "infer_list_[" << cur_infer_id
264	                              << "] is null inside run_infer_step.";
265	
266	      // Check iter_var->dom and dom->extent
267	      ICHECK(iter_var.defined())
268	          << "thread_var_vec_[" << cur_infer_id << "] is not defined.";
269	      ICHECK(iter_var->dom.defined())
270	          << "iter_var->dom is not defined for infer_list_[" << cur_infer_id
271	          << "].";
272	      ICHECK(iter_var->dom->extent.defined())
273	          << "iter_var->dom->extent is not defined for infer_list_["
274	          << cur_infer_id << "].";
275	
276	      const int64_t *extent_ptr = as_const_int(iter_var->dom->extent);
277	      ICHECK(extent_ptr != nullptr)
278	          << "iter_var->dom->extent is not a constant integer, which is "
279	             "required for layout inference.";
280	
281	      // Run InferLayout
282	      auto updates = next->InferLayout(
283	          LayoutInferArgs{target_, thread_bounds, layout_map}, level);
284	      // Process the returned updates
285	      for (const auto &[buffer, layout] : updates) {
286	        // Basic validity checks
287	        ICHECK(buffer.defined()) << "InferLayout returned an undefined buffer.";
288	        ICHECK(layout.defined()) << "InferLayout returned an undefined layout.";
289	
290	        if (layout_map.count(buffer)) {
291	          // If already in map, ensure they are structurally equal
292	          ICHECK(StructuralEqual()(layout, layout_map[buffer]))
293	              << "Get different layout for " << buffer
294	              << "\n current layout: " << layout->DebugOutput()
295	              << "\n previous layout: " << layout_map[buffer]->DebugOutput();
296	        } else {
297	          // Otherwise, update map
298	          layout_map.Set(buffer, layout);
299	          if (!update_queue)
300	            continue;
301	
302	          // Check if buffer exists in use_list_
303	          if (!use_list_.count(buffer)) {
304	            LOG(WARNING) << "Layout inference failed for buffer " << buffer
305	                         << ". "
306	                         << "The buffer cannot be inferred with current layout "
307	                            "inference rules.";
308	            continue;
309	          }
310	
311	          // Push back into BFS queue
312	          for (int idx : use_list_[buffer]) {
313	            ICHECK_GE(idx, 0) << "Index in use_list_ for buffer " << buffer
314	                              << " is negative.";
315	            ICHECK_LT(idx, num_infer)
316	                << "Index in use_list_ for buffer " << buffer
317	                << " out of range: " << idx << " >= " << num_infer << ".";
318	
319	            if (!in_queue[idx] && idx != cur_infer_id) {
320	              in_queue[idx] = true;
321	              q.push(idx);
322	            }
323	          }
324	        }
325	      }
326	    };
327	
328	    auto finish_infer_queue = [&]() {
329	      while (!q.empty()) {
330	        int cur_infer_id = q.front();
331	        q.pop();
332	        // Range check again, just to be safe
333	        ICHECK_GE(cur_infer_id, 0);
334	        ICHECK_LT(cur_infer_id, num_infer);
335	
336	        in_queue[cur_infer_id] = false;
337	        run_infer_step(cur_infer_id, InferLevel::kCommon, true);
338	      }
339	    };
340	
341	    // step 1: infer strict layout
342	    for (int i = 0; i < num_infer; i++) {
343	      run_infer_step(i, InferLevel::kStrict, false);
344	    }
345	
346	    // step 2: infer common layout with BFS
347	    finish_infer_queue();
348	
349	    // step 3: relax constraints to free and re-run
350	    for (int i = 0; i < num_infer; i++) {
351	      run_infer_step(i, InferLevel::kFree, true);
352	      finish_infer_queue();
353	    }
354	
355	    // Check that all local.fragment buffers have inferred layouts
356	    for (const auto &[buffer, _] : use_list_) {
357	      if (buffer.scope() == "local.fragment") {
358	        ICHECK_NE(layout_map.count(buffer), 0)
359	            << "The layout for fragment " << buffer
360	            << " can not be inferred correctly.";
361	      }
362	    }
363	
364	    // Collect layout info for For nodes
365	    Map<For, Fragment> for_map;
366	    Map<For, PrimExpr> predicate_map;
367	    ICHECK(infer_list_.size() == thread_var_vec_.size())
368	        << "infer_list_ and thread_var_vec_ size mismatch";
369	    for (int i = 0; i < infer_list_.size(); i++) {
370	      std::unique_ptr<Operator> base_infer = std::move(infer_list_[i]);
371	      auto thread_var = thread_var_vec_[i];
372	
373	      // Check if base_infer is valid
374	      ICHECK(base_infer != nullptr) << "Null pointer encountered in "
375	                                       "infer_list_ while collecting for_map.";
376	      if (auto for_infer = dynamic_cast<ParallelOp *>(base_infer.get())) {
377	        // Check that the loop layout is defined
378	        ICHECK(for_infer->GetLoopLayout().defined())
379	            << "The Layout for Parallel for cannot be inferred correctly:\n"
380	            << for_infer->GetRoot();
381	        for_map.Set(for_infer->GetRoot(), for_infer->GetLoopLayout());
382	        // thread_var_ should be defined if we rely on it
383	        ICHECK(thread_var.defined())
384	            << "thread_var is not defined. Cannot retrieve predicate.";
385	
386	        if (auto predicate = for_infer->GetPredicate(thread_var->var)) {
387	          predicate_map.Set(for_infer->GetRoot(), predicate.value());
388	        }
389	      }
390	    }
391	
392	    return {layout_map, for_map, predicate_map};
393	  }
394	
395	  void Collect(const PrimFunc &f) {
396	    for (const auto &[_, buffer] : f->buffer_map) {
397	      buffer_data_to_buffer_.Set(buffer->data, buffer);
398	    }
399	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
400	    ICHECK(target.defined())
401	        << "Layout_Inference: Require the target attribute";
402	    target_ = target.value();
403	    this->operator()(f->body);
404	  }
405	
406	private:
407	  void VisitExpr_(const CallNode *op) final {
408	    IRVisitorWithAnalyzer::VisitExpr_(op);
409	    // Do not analysis the call node to the global function.
410	    if (op->op.as<GlobalVarNode>())
411	      return;
412	
413	    auto p = ParseOperator(GetRef<Call>(op), buffer_data_to_buffer_);
414	    if (p != nullptr) {
415	      for (const auto &arg : op->args) {
416	        if (auto buffer = getBufferFromAccessPtr(arg)) {
417	          addToUseList(buffer.value());
418	        }
419	      }
420	      infer_list_.push_back(std::move(p));
421	      thread_var_vec_.push_back(thread_var_);
422	      if (analyzer_.const_int_bound.IsBound(thread_var_->var)) {
423	        auto const_int_bound = analyzer_.const_int_bound(thread_var_);
424	        auto min_value = const_int_bound->min_value;
425	        auto max_value = const_int_bound->max_value;
426	        auto extent = max_value - min_value + 1;
427	        auto dtype = thread_var_->var.dtype();
428	        thread_bounds_vec_.push_back(Range::FromMinExtent(
429	            IntImm(dtype, min_value), IntImm(dtype, extent)));
430	      } else {
431	        thread_bounds_vec_.push_back(Range::FromMinExtent(0, 1));
432	      }
433	    }
434	  }
435	
436	  Optional<Buffer> getBufferFromAccessPtr(const PrimExpr &expr) {
437	    auto call = expr.as<CallNode>();
438	    if (call && call->op.same_as(builtin::tvm_access_ptr())) {
439	      auto var = call->args[1].as<Var>().value();
440	      return buffer_data_to_buffer_[var];
441	    }
442	    return NullOpt;
443	  }
444	
445	  void addToUseList(const Buffer &buffer) {
446	    int infer_idx = infer_list_.size();
447	    if (use_list_.find(buffer) == use_list_.end()) {
448	      use_list_[buffer] = {};
449	    }
450	    use_list_[buffer].push_back(infer_idx);
451	  }
452	
453	  void VisitStmt_(const ForNode *op) final {
454	    if (op->kind == ForKind::kParallel) {
455	      auto infer = std::make_unique<ParallelOp>(GetRef<For>(op));
456	      for (const auto &[buffer, _] : infer->GetIndiceMap()) {
457	        addToUseList(buffer);
458	      }
459	      infer_list_.push_back(std::move(infer));
460	      thread_var_vec_.push_back(thread_var_);
461	      if (thread_var_.defined() &&
462	          analyzer_.const_int_bound.IsBound(thread_var_->var)) {
463	        auto const_int_bound = analyzer_.const_int_bound(thread_var_);
464	        auto dtype = thread_var_->var.dtype();
465	        auto extent =
466	            const_int_bound->max_value - const_int_bound->min_value + 1;
467	        thread_bounds_vec_.push_back(Range::FromMinExtent(
468	            IntImm(dtype, const_int_bound->min_value), IntImm(dtype, extent)));
469	      } else {
470	        thread_bounds_vec_.push_back(Range::FromMinExtent(0, 1));
471	      }
472	    } else {
473	      IRVisitorWithAnalyzer::VisitStmt(op->body);
474	    }
475	  }
476	
477	  void VisitStmt_(const BlockNode *op) final {
478	    for (auto buffer : op->alloc_buffers) {
479	      buffer_data_to_buffer_.Set(buffer->data, buffer);
480	    }
481	    if (op->annotations.count(attr::kLayoutMap)) {
482	      auto map =
483	          op->annotations.Get(attr::kLayoutMap).as<Map<Var, Layout>>().value();
484	      for (auto it : map) {
485	        Var target_var = it.first;
486	        Layout target_layout = it.second;
487	        Buffer found_buffer;
488	        if (buffer_data_to_buffer_.count(target_var)) {
489	          found_buffer = buffer_data_to_buffer_[target_var];
490	        } else {
491	          for (auto const &kv : buffer_data_to_buffer_) {
492	            Var current_var = kv.first;
493	            Buffer current_buf = kv.second;
494	            if (current_var->name_hint == target_var->name_hint &&
495	                StructuralEqual()(current_buf->shape,
496	                                  target_layout->InputShape()) &&
497	                current_var->dtype == target_var->dtype) {
498	              found_buffer = current_buf;
499	              break;
500	            }
501	          }
502	        }
503	        if (!found_buffer.defined()) {
504	          ICHECK(false) << "Buffer " << target_var->name_hint
505	                        << " has no matching definition in this scope.";
506	        }
507	        annotated_layout_map_.Set(found_buffer, target_layout);
508	      }
509	    }
510	    IRVisitorWithAnalyzer::VisitStmt_(op);
511	  }
512	
513	  void VisitStmt_(const AttrStmtNode *op) final {
514	    if (op->attr_key == tir::attr::thread_extent) {
515	      IterVar iv = Downcast<IterVar>(op->node);
516	      if (iv->thread_tag == "threadIdx.x") {
517	        ICHECK(iv->dom->extent.as<IntImmNode>());
518	        thread_var_ = iv;
519	      }
520	    }
521	    IRVisitorWithAnalyzer::VisitStmt_(op);
522	  }
523	
524	  Map<Var, Buffer> buffer_data_to_buffer_;
525	  std::vector<std::unique_ptr<Operator>> infer_list_;
526	  std::unordered_map<Buffer, std::vector<int>, ObjectPtrHash, ObjectPtrEqual>
527	      use_list_;
528	  // This is a workaround for cpu backend,
529	  // we need to define a thread_var for the serial loop.
530	  IterVar thread_var_ = IterVar(Range::FromMinExtent(0, 1), Var("v_thread"),
531	                                IterVarType::kDataPar);
532	  std::vector<IterVar> thread_var_vec_;
533	  std::vector<Range> thread_bounds_vec_;
534	  Target target_;
535	  LayoutMap annotated_layout_map_;
536	  bool skip_thread_partition_{false};
537	};
538	
539	class LayoutInferencer : public IRMutatorWithAnalyzer {
540	public:
541	  static PrimFunc Substitute(PrimFunc f, bool skip_thread_partition = false) {
542	    arith::Analyzer analyzer;
543	    PrimFuncNode *fptr = f.CopyOnWrite();
544	    fptr->body = ParallelLoopFuser::Fuse(f->body);
545	    BufferUseDefCollector collector(skip_thread_partition);
546	    collector.Collect(f);
547	    auto result = collector.Run();
548	    LayoutInferencer substituter(result, skip_thread_partition, &analyzer);
549	    fptr->body = substituter.VisitStmt(f->body);
550	    auto fn_attr = fptr->attrs.CopyOnWrite();
551	    fn_attr->dict.Set("address_map", substituter.address_map_);
552	    return f;
553	  }
554	
555	private:
556	  LayoutInferencer(const LayoutInferenceResult result,
557	                   bool skip_thread_partition, arith::Analyzer *analyzer)
558	      : arith::IRMutatorWithAnalyzer(analyzer), result_(result),
559	        skip_thread_partition_(skip_thread_partition) {};
560	
561	  Stmt VisitStmt_(const BlockNode *op) final {
562	    Block block = Downcast<Block>(IRMutatorWithAnalyzer::VisitStmt_(op));
563	
564	    for (auto buffer : block->alloc_buffers) {
565	      if (buffer.scope() == "local.framgent") {
566	        ICHECK(result_.layout_map.count(buffer))
567	            << "Cannot inference fragment layout for " << buffer;
568	      }
569	    }
570	    if (op->annotations.count("address_map")) {
571	      address_map_ =
572	          op->annotations.at("address_map").as<Map<Var, PrimExpr>>().value();
573	    }
574	    auto block_ptr = block.CopyOnWrite();
575	    block_ptr->annotations.Set(attr::kLayoutMap, result_.layout_map);
576	    return block;
577	  }
578	
579	  Stmt VisitStmt_(const ForNode *op) final {
580	    For for_node = Downcast<For>(IRMutatorWithAnalyzer::VisitStmt_(op));
581	    if (result_.for_map.count(GetRef<For>(op))) {
582	      auto root = GetRef<For>(op);
583	      // This check is a workaround to support T.Parallel for local buffers.
584	      // For example:
585	      //   for i in T.Parallel(1024):
586	      //     A_local[i] = A_global[i]
587	      // Here, A_local is a register-local buffer held independently by each
588	      // thread, so explicit thread binding is not required.
589	      //
590	      // We use PostOrderVisit to detect whether the buffer store targets a
591	      // "local" buffer, which indicates register usage and justifies skipping
592	      // thread binding.
593	      bool is_register_store = false;
594	      PostOrderVisit(root, [&](const ObjectRef &obj) {
595	        if (const auto *store = obj.as<BufferStoreNode>()) {
596	          if (store->buffer.scope() == "local") {
597	            is_register_store = true;
598	          }
599	        }
600	      });
601	
602	      auto loop_layout = result_.for_map[root];
603	      bool parallel_loop = !is_register_store && !skip_thread_partition_;
604	      if (parallel_loop) {
605	        for_node =
606	            PartitionLoop(for_node, thread_var_->var, analyzer_, loop_layout);
607	      }
608	      // If none thread bindings are provided, partition the loop
609	      bool has_non_local = false;
610	      PostOrderVisit(for_node->body, [&](const ObjectRef &obj) {
611	        if (const auto *load = obj.as<BufferLoadNode>()) {
612	          String scope = load->buffer.scope();
613	          if (scope != "local" && scope != "local.fragment") {
614	            has_non_local = true;
615	          }
616	        } else if (const auto *store = obj.as<BufferStoreNode>()) {
617	          String scope = store->buffer.scope();
618	          if (scope != "local" && scope != "local.fragment") {
619	            has_non_local = true;
620	          }
621	        }
622	      });
623	
624	      if (has_non_local) {
625	        for_node = VectorizeLoop(for_node);
626	      }
627	
628	      if (result_.predicate_map.count(root) && parallel_loop) {
629	        return IfThenElse(result_.predicate_map[root], for_node);
630	      } else {
631	        return for_node;
632	      }
633	    }
634	    return for_node;
635	  }
636	
637	  Stmt VisitStmt_(const AttrStmtNode *op) final {
638	    if (op->attr_key == tir::attr::thread_extent) {
639	      IterVar iv = Downcast<IterVar>(op->node);
640	      ICHECK_NE(iv->thread_tag.length(), 0U);
641	      if (iv->thread_tag == "threadIdx.x") {
642	        thread_var_ = iv;
643	      }
644	    }
645	    return IRMutatorWithAnalyzer::VisitStmt_(op);
646	  }
647	
648	private:
649	  const LayoutInferenceResult result_;
650	  IterVar thread_var_ = IterVar(Range::FromMinExtent(0, 1), Var("v_thread"),
651	                                IterVarType::kDataPar);
652	  bool skip_thread_partition_{false};
653	
654	  Map<Var, PrimExpr> address_map_;
655	};
656	
657	tvm::transform::Pass LayoutInference() {
658	  using namespace tir::transform;
659	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
660	    f.CopyOnWrite()->body = ParallelLoopTransformer::Substitute(f->body);
661	    ThreadBindingCollector collector;
662	    collector(f->body);
663	    bool has_thread_binding = collector.thread_binding_.size() > 0;
664	    bool skip_thread_partition = !has_thread_binding;
665	    return LayoutInferencer::Substitute(std::move(f), skip_thread_partition);
666	  };
667	  return CreatePrimFuncPass(pass_func, 0, "tl.LayoutInference", {});
668	}
669	
670	TVM_REGISTER_GLOBAL("tl.transform.LayoutInference")
671	    .set_body_typed(LayoutInference);
672	
673	} // namespace tl
674	} // namespace tvm
